#include <sys/inotify.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <stdio.h>

int create_inotify_instance(int flags) {
    // Check if inotify is supported by the system
    if (!is_inotify_supported()) {
        return -ENOSYS;
    }

    // Validate flags against defined constants
    if ((flags & ~(IN_CLOEXEC | IN_NONBLOCK)) != 0) {
        return -EINVAL;
    }

    // Retrieve current user and check if user has exceeded inotify limits
    uid_t user_id = get_current_user();
    if (is_user_inotify_limit_reached(user_id)) {
        return -ENFILE;
    }

    // Create a new fsnotify group for inotify events
    struct fsnotify_group *group = create_fsnotify_group();
    if (!group) {
        return -ENOMEM;
    }

    // Attempt to obtain file descriptor for the inotify instance
    int fd = inotify_alloc_fd(group, flags);
    if (fd < 0) {
        // Clean up resources if failure
        release_fsnotify_group(group);
        return fd;
    }

    return fd;
}

